import streamlit as st

# 1. Configuração da Página (Importante para o Google e visualização em abas)
st.set_page_config(
    page_title="Soluções em Processamento de Dados | Sua Empresa",
    page_icon="📊",
    layout="centered" # Garante um design minimalista e bem centralizado
)

# 2. CSS Customizado para Minimalismo
st.markdown("""
    <style>
    /* Ocultar menu padrão do Streamlit para visual mais limpo */
    #MainMenu {visibility: hidden;}
    footer {visibility: hidden;}
    header {visibility: hidden;}
    
    /* Estilização do botão de contato */
    .stButton>button {
        width: 100%;
        background-color: #0066cc;
        color: white;
        border-radius: 5px;
    }
    .stButton>button:hover {
        background-color: #0052a3;
        color: white;
    }
    </style>
""", unsafe_allow_html=True)

# 3. Cabeçalho Principal (Hero Section)
st.title("Transforme seus dados em resultados 📈")
st.markdown("Ajudamos **pequenas empresas** a economizar tempo e dinheiro através da automação inteligente e do processamento de dados. Deixe o trabalho manual conosco e foque no crescimento do seu negócio.")
st.divider()

# 4. Seção de Serviços (Com espaço para 2 imagens)
st.header("Nossos Serviços")

# Cria duas colunas responsivas (lado a lado no PC, uma sobre a outra no Celular)
col1, col2 = st.columns(2)

with col1:
    st.subheader("Automação de Tarefas")
    st.write("Eliminamos processos manuais repetitivos. Automatizamos a coleta, formatação e organização de planilhas e relatórios diários.")
    # Espaço para a Imagem 1
    # Substitua 'imagem1.jpg' pelo caminho ou URL da sua imagem
    st.image("data:image/jpeg;base64,", caption="Automação de Processos")

with col2:
    st.subheader("Estruturação de Dados")
    st.write("Limpamos, organizamos e estruturamos grandes volumes de dados desorganizados para que você possa tomar decisões estratégicas com clareza.")
    # Espaço para a Imagem 2
    # Substitua 'imagem2.jpg' pelo caminho ou URL da sua imagem
    st.image("data:image/jpeg;base64,", caption="Limpeza e Estruturação")

st.divider()

# 5. Seção de Contato
st.header("Fale Conosco")
st.write("Pronto para otimizar o tempo da sua equipe? Preencha o formulário abaixo ou entre em contato diretamente.")

# Formulário simples de contato (usando formsubmit para enviar direto para seu email sem backend complexo)
# Substitua SEU_EMAIL_AQUI pelo email da sua empresa
contact_form = """
<form action="https://formsubmit.co/SEU_EMAIL_AQUI@dominio.com" method="POST">
     <input type="hidden" name="_captcha" value="false">
     <input type="text" name="name" placeholder="Seu Nome ou Empresa" required style="width:100%; padding:10px; margin-bottom:10px; border:1px solid #ccc; border-radius:4px;">
     <input type="email" name="email" placeholder="Seu E-mail" required style="width:100%; padding:10px; margin-bottom:10px; border:1px solid #ccc; border-radius:4px;">
     <textarea name="message" placeholder="Como podemos ajudar na sua automação?" required style="width:100%; padding:10px; margin-bottom:10px; border:1px solid #ccc; border-radius:4px;"></textarea>
     <button type="submit" style="width:100%; padding:10px; background-color:#0066cc; color:white; border:none; border-radius:4px; cursor:pointer;">Enviar Mensagem</button>
</form>
"""
st.markdown(contact_form, unsafe_allow_html=True)